@Component("carrierService-handler")
@ProcessingGroup("carrierService-processing-group")
public class CarrierServiceEventHandler {
	
	// core constructor
	CarrierServiceEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCarrierServiceEvent
     */
    @EventHandler
    public void handle( CreateCarrierServiceEvent event) {
        entityManager.persist(new CarrierService(event.getCarrierServiceId(), event.getName(), event.getCode(), event.getShippingMethods(), event.getCarrier(), event.getServiceLevel()));
    }

    /*
     * @param	event UpdateCarrierServiceEvent
     */
    @EventHandler
    public CarrierService handle( UpdateCarrierServiceEvent event) {
    	entityManager.merge(new CarrierService(event.getCarrierServiceId(), event.getName(), event.getCode(), event.getShippingMethods(), event.getCarrier(), event.getServiceLevel()));
    }
    
    /*
     * @param	event DeleteCarrierServiceEvent
     */
    @EventHandler
    public void on( DeleteCarrierServiceEvent event) {
    	CarrierService entity = new CarrierService();
   
    	// ------------------------------------------
    	// apply the CarrierServiceId
    	// ------------------------------------------
    	entity.setCarrierServiceId( event.getCarrierServiceId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CarrierServiceRepository carrierServiceEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CarrierServiceEventHandler.class.getName());

}
